SELECT time, pid, process_name, netconn_domain, remote_ip, remote_port, source_stream, event_record_id, event_id, subject_user_name
FROM audit_logs
WHERE ppid IN (
    SELECT pid FROM audit_logs
    WHERE process_name LIKE '%cmd.exe%'
) AND process_name LIKE '%python.exe%' AND command_line LIKE '%python%' AND access = 'connect';

